<script src="{{ asset('admin/dist') }}/assets/libs/apexcharts/apexcharts.min.js"></script><script>let mc;function loadM(){const month=$('#mMonth').val();const start=`${month}-01`;const dt=new Date(`${month}-01T00:00:00`);const end=new Date(dt.getFullYear(),dt.getMonth()+1,0);const endStr=`${end.getFullYear()}-${String(end.getMonth()+1).padStart(2,'0')}-${String(end.getDate()).padStart(2,'0')}`;$('#mExport').attr('href',`{{ route('consumptionData.export') }}?period=${encodeURIComponent(start+' to '+endStr)}`);fetch(`{{ route('reports.monthly.api') }}?month=${encodeURIComponent(month)}`).then(r=>r.json()).then(d=>{$('#mTotal').text(d.summary.total);$('#mBreakfast').text(d.summary.breakfast);$('#mLunch').text(d.summary.lunch);$('#mDinner').text(d.summary.dinner);$('#mBody').html(d.daily.length?d.daily.map(x=>`<tr><td>${x.date}</td><td><strong>${x.total}</strong></td><td>${x.breakfast}</td><td>${x.lunch}</td><td>${x.dinner}</td></tr>`).join(''):'<tr><td colspan="5"><div class="mc-empty">No monthly data</div></td></tr>');if(mc)mc.destroy();mc=new ApexCharts(document.querySelector('#monthlyChart'),{chart:{type:'area',height:360,toolbar:{show:false}},series:[{name:'Breakfast',data:d.daily.map(x=>x.breakfast)},{name:'Lunch',data:d.daily.map(x=>x.lunch)},{name:'Dinner',data:d.daily.map(x=>x.dinner)}],xaxis:{categories:d.daily.map(x=>x.date.slice(-2))},stroke:{curve:'smooth',width:2},colors:['#16a34a','#ea580c','#0891b2'],dataLabels:{enabled:false},legend:{position:'top'},fill:{type:'gradient',gradient:{opacityFrom:.16,opacityTo:.02}}});mc.render();});}$('#mApply').click(loadM);loadM();</script>
